steps.raw:
SELECT player_id FROM (
  SELECT player_id, COUNT(DISTINCT tourney_id) AS tourney_count FROM (
    SELECT winner_id AS player_id, tourney_id FROM matches
    UNION ALL
    SELECT loser_id AS player_id, tourney_id FROM matches
  )
  GROUP BY player_id
)
ORDER BY tourney_count DESC
LIMIT 1;

