WITH total_earnings AS (
  SELECT SUM(Earnings) AS sum_earnings FROM poker_player
),
player_count AS (
  SELECT COUNT(*) AS total_players FROM poker_player
)
SELECT 
  total_earnings.sum_earnings * 1.0 / player_count.total_players AS Average_Earnings
FROM 
  total_earnings, player_count;

